                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_power(M, n, mod):
        """Compute M^n mod m using binary exponentiation"""
        if n == 1:
            return M

        # Start with identity matrix
        result = [[1, 0], [0, 1]]
        base = [row[:] for row in M]  # Copy M

        while n > 0:
            if n % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            n //= 2

        return result

    result_matrix = matrix_power(M, power, modulus)

    # Sum all entries
